<script lang="ts">
 import type {Project,PVModule,Inverter,ExtraItem}from '../model';
 import {nowId}from '../model';import {panels,inverters}from '../data/equipment';
 import {design,num,price,areaStats}from '../engine/calculate';
 export let project:Project;export let update:(p:Partial<Project>)=>void;
 $: d=design(project);
 $: availablePanels=[...panels,...project.customPanels];
 $: availableInverters=[...inverters,...project.customInverters];
 $: panelBrands=[...new Set(availablePanels.map(p=>p.brand))];
 $: inverterBrands=[...new Set(availableInverters.map(p=>p.brand))];
 let panelBrand='Trina Solar';let inverterBrand='Growatt';
 let panelForm=false;let inverterForm=false;
 let panelDraft={brand:'',model:'',powerW:550,lengthMm:2250,widthMm:1134,voc:50,vmp:42,isc:14,imp:13,tempVocPct:-0.25,tempPowerPct:-0.3,efficiencyPct:21};
 let inverterDraft={brand:'',model:'',type:'grid',acKw:10,mpptCount:2,stringsPerMppt:1,mpptMin:120,mpptMax:800,maxVdc:1000,inputCurrentA:16,shortCircuitCurrentA:20,efficiencyPct:97,phase:'three'};
 const n=(e:Event)=>Number((e.currentTarget as HTMLInputElement).value);
 const pricePerW=()=>d.panel?.powerW?project.panelPrice/d.panel.powerW:0;
 function addPanel(){if(!panelDraft.brand.trim()||!panelDraft.model.trim()||panelDraft.powerW<=0||panelDraft.voc<=0||panelDraft.vmp<=0)return;const id=nowId();const model={...panelDraft,id,source:'User-entered; verify against manufacturer datasheet',verified:false} as PVModule;update({customPanels:[...project.customPanels,model],panelId:id});panelBrand=panelDraft.brand;panelForm=false;}
 function addInverter(){if(!inverterDraft.brand.trim()||!inverterDraft.model.trim()||inverterDraft.acKw<=0)return;const id=nowId();const model={...inverterDraft,id,source:'User-entered; verify against manufacturer datasheet',verified:false} as Inverter;update({customInverters:[...project.customInverters,model],inverterId:id});inverterBrand=inverterDraft.brand;inverterForm=false;}
 function addExtra(){const x:ExtraItem={id:nowId(),type:'سایر',title:'',unit:'عدد',quantity:1,unitPrice:0};update({extras:[...project.extras,x]});}
 function editExtra(id:string,field:keyof ExtraItem,value:string|number){update({extras:project.extras.map(x=>x.id===id?{...x,[field]:value}:x)});}
</script>
<section class="stage-heading"><h1>انتخاب تجهیزات و طراحی آرایه</h1><p>مدل پنل و اینورتر را انتخاب کنید؛ آرایش رشته‌ها و هزینه‌ها در همه مراحل به‌روز می‌شوند.</p></section>
<div class="layout-two">
 <div class="panel"><div class="panel-head"><h2>انتخاب پنل خورشیدی</h2><button type="button" class="btn btn-outline btn-small" onclick={()=>panelForm=!panelForm}>+ افزودن مدل</button></div><div class="form-grid"><label>برند پنل<select bind:value={panelBrand}>{#each panelBrands as b}<option value={b}>{b}</option>{/each}</select></label><label>مدل و ظرفیت<select value={project.panelId} onchange={e=>update({panelId:e.currentTarget.value})}>{#each availablePanels.filter(p=>p.brand===panelBrand) as p}<option value={p.id}>{p.model} — {num(p.powerW)} W</option>{/each}</select></label><label>قیمت هر پنل (ریال)<input type="number" min="0" step="1000" value={project.panelPrice} oninput={e=>update({panelPrice:n(e)})}/></label><label>قیمت هر وات (ریال/Wp)<input type="number" min="0" step="1" value={pricePerW()} oninput={e=>update({panelPrice:Math.round(n(e)*(d.panel?.powerW||0))})}/></label></div>
 {#if d.panel}<div class="spec-grid"><span>توان <b>{num(d.panel.powerW)} W</b></span><span>ابعاد <b>{num(d.panel.lengthMm)}×{num(d.panel.widthMm)} mm</b></span><span>Voc <b>{num(d.panel.voc,2)} V</b></span><span>Vmp <b>{num(d.panel.vmp,2)} V</b></span><span>Isc <b>{num(d.panel.isc,2)} A</b></span><span>Imp <b>{num(d.panel.imp,2)} A</b></span><span>راندمان <b>{num(d.panel.efficiencyPct,1)}%</b></span><span>منبع <b>{d.panel.verified?'دیتاشیت':'ورود کاربر / تأییدنشده'}</b></span></div>{/if}
 {#if panelForm}<div class="editor"><h3>مدل پنل جدید (نیازمند تأیید دیتاشیت)</h3><div class="form-grid"><label>برند<input bind:value={panelDraft.brand}/></label><label>مدل<input bind:value={panelDraft.model}/></label><label>توان W<input type="number" bind:value={panelDraft.powerW}/></label><label>طول mm<input type="number" bind:value={panelDraft.lengthMm}/></label><label>عرض mm<input type="number" bind:value={panelDraft.widthMm}/></label><label>Voc (V)<input type="number" step="0.1" bind:value={panelDraft.voc}/></label><label>Vmp (V)<input type="number" step="0.1" bind:value={panelDraft.vmp}/></label><label>Isc (A)<input type="number" step="0.01" bind:value={panelDraft.isc}/></label><label>Imp (A)<input type="number" step="0.01" bind:value={panelDraft.imp}/></label><label>ضریب دمای Voc (%/°C)<input type="number" step="0.01" bind:value={panelDraft.tempVocPct}/></label></div><button type="button" class="btn btn-primary" onclick={addPanel}>ثبت مدل پنل</button></div>{/if}
 </div>
 <div class="panel"><div class="panel-head"><h2>انتخاب اینورتر</h2><button type="button" class="btn btn-outline btn-small" onclick={()=>inverterForm=!inverterForm}>+ افزودن مدل</button></div><div class="form-grid"><label>برند اینورتر<select bind:value={inverterBrand}>{#each inverterBrands as b}<option value={b}>{b}</option>{/each}</select></label><label>مدل / توان<select value={project.inverterId} onchange={e=>update({inverterId:e.currentTarget.value})}>{#each availableInverters.filter(x=>x.brand===inverterBrand) as x}<option value={x.id}>{x.model} — {num(x.acKw)} kW</option>{/each}</select></label><label>تعداد اینورتر<input type="number" min="1" step="1" value={project.layout.inverterCount} oninput={e=>update({layout:{...project.layout,inverterCount:n(e)}})}/></label><label>قیمت هر اینورتر (ریال)<input type="number" min="0" step="1000" value={project.inverterPrice} oninput={e=>update({inverterPrice:n(e)})}/></label></div>
 {#if d.inverter}<div class="spec-grid"><span>AC <b>{num(d.inverter.acKw)} kW</b></span><span>MPPT <b>{num(d.inverter.mpptCount)}</b></span><span>محدوده MPPT <b>{num(d.inverter.mpptMin)}–{num(d.inverter.mpptMax)} V</b></span><span>حداکثر DC <b>{num(d.inverter.maxVdc)} V</b></span><span>جریان MPPT <b>{num(d.inverter.inputCurrentA)} A</b></span><span>فاز <b>{d.inverter.phase==='three'?'سه‌فاز':'تک‌فاز'}</b></span></div>{/if}
 {#if inverterForm}<div class="editor"><h3>مدل اینورتر جدید (مشخصات ورودی نیازمند تأیید)</h3><div class="form-grid"><label>برند<input bind:value={inverterDraft.brand}/></label><label>مدل<input bind:value={inverterDraft.model}/></label><label>نوع<select bind:value={inverterDraft.type}><option value="grid">On-grid</option><option value="hybrid">Hybrid</option><option value="offgrid">Off-grid</option></select></label><label>توان AC kW<input type="number" bind:value={inverterDraft.acKw}/></label><label>MPPT Count<input type="number" bind:value={inverterDraft.mpptCount}/></label><label>ورودی رشته / MPPT<input type="number" bind:value={inverterDraft.stringsPerMppt}/></label><label>حداقل MPPT V<input type="number" bind:value={inverterDraft.mpptMin}/></label><label>حداکثر MPPT V<input type="number" bind:value={inverterDraft.mpptMax}/></label><label>حداکثر DC V<input type="number" bind:value={inverterDraft.maxVdc}/></label><label>جریان مجاز MPPT A<input type="number" bind:value={inverterDraft.inputCurrentA}/></label><label>جریان اتصال کوتاه A<input type="number" bind:value={inverterDraft.shortCircuitCurrentA}/></label></div><button type="button" class="btn btn-primary" onclick={addInverter}>ثبت مدل اینورتر</button></div>{/if}
 </div>
</div>
<div class="layout-two lower-cards">
 <div class="panel"><div class="panel-head"><h2>طراحی اولیه آرایه و رشته‌بندی</h2><div class="toggle"><button type="button" class:chosen={project.layout.mode==='auto'} onclick={()=>update({layout:{...project.layout,mode:'auto'}})}>خودکار</button><button type="button" class:chosen={project.layout.mode==='manual'} onclick={()=>update({layout:{...project.layout,mode:'manual'}})}>دستی</button></div></div><div class="form-grid"><label>جهت قرارگیری پنل<select value={project.layout.direction} onchange={e=>update({layout:{...project.layout,direction:e.currentTarget.value as 'portrait'|'landscape'}})}><option value="portrait">عمودی (Portrait)</option><option value="landscape">افقی (Landscape)</option></select></label><label>تعداد پنل<input type="number" min="0" step="1" disabled={project.layout.mode==='auto'} value={d.panelCount} oninput={e=>update({layout:{...project.layout,panelCount:n(e)}})}/></label><label>تعداد پنل در هر رشته<input type="number" min="1" step="1" value={project.layout.series} oninput={e=>update({layout:{...project.layout,series:n(e)}})}/></label><label>ضریب تراکم چیدمان<input type="number" min="0.3" max="1" step="0.01" value={project.layout.packingFactor} oninput={e=>update({layout:{...project.layout,packingFactor:n(e)}})}/></label><label>دمای حداقل محیط °C<input type="number" value={project.layout.ambientColdC} oninput={e=>update({layout:{...project.layout,ambientColdC:n(e)}})}/></label><label>دمای سلول در گرما °C<input type="number" value={project.layout.ambientHotC} oninput={e=>update({layout:{...project.layout,ambientHotC:n(e)}})}/></label></div><div class="hint">تعداد Auto = مساحت مفید × ضریب تراکم ÷ مساحت ماژول؛ جانمایی هندسی و سایه‌اندازی هنوز شبیه‌سازی نشده است.</div></div>
 <div class="panel"><div class="panel-head"><h2>خلاصه و کنترل سازگاری</h2><span class="chip" class:bad={d.errors.length>0}>{d.errors.length?'نیازمند اصلاح':'کنترل مقدماتی'}</span></div><div class="spec-grid large"><span>پنل نصب‌شده <b>{num(d.installedPanels)}</b></span><span>رشته‌ها <b>{num(d.strings)}</b></span><span>تعداد اینورتر <b>{num(d.inverters)}</b></span><span>DC <b>{num(d.dcKw,2)} kWp</b></span><span>AC <b>{num(d.acKw,2)} kW</b></span><span>DC/AC <b>{d.ratio===null?'—':num(d.ratio,2)}</b></span><span>Voc سرد <b>{d.vCold===null?'—':num(d.vCold,1)+' V'}</b></span><span>Imp/MPPT <b>{d.impPerMppt===null?'—':num(d.impPerMppt,2)+' A'}</b></span></div>{#each d.errors as error}<div class="message message-error">✕ {error}</div>{/each}{#each d.warnings as warning}<div class="message message-warning">! {warning}</div>{/each}</div>
</div>
<div class="panel"><div class="panel-head"><h2>سایر تجهیزات پروژه و هزینه‌ها</h2><button class="btn btn-primary btn-small" type="button" onclick={addExtra}>+ افزودن تجهیز</button></div><div class="table-scroll"><table><thead><tr><th>نوع تجهیز</th><th>شرح</th><th>واحد</th><th>مقدار</th><th>قیمت واحد (ریال)</th><th>جمع (ریال)</th><th></th></tr></thead><tbody>{#each project.extras as x (x.id)}<tr><td><select value={x.type} onchange={e=>editExtra(x.id,'type',e.currentTarget.value)}>{#each ['سازه','کابل DC','کابل AC','تابلو و حفاظت','باتری','ارتینگ','نصب و اجرا','سایر'] as k}<option value={k}>{k}</option>{/each}</select></td><td><input value={x.title} placeholder="شرح یا مدل تجهیز" oninput={e=>editExtra(x.id,'title',e.currentTarget.value)}/></td><td><select value={x.unit} onchange={e=>editExtra(x.id,'unit',e.currentTarget.value)}>{#each ['عدد','متر','مترمربع','کیلوگرم','دستگاه','سری'] as u}<option value={u}>{u}</option>{/each}</select></td><td><input type="number" min="0" step="0.1" value={x.quantity} oninput={e=>editExtra(x.id,'quantity',n(e))}/></td><td><input type="number" min="0" step="1000" value={x.unitPrice} oninput={e=>editExtra(x.id,'unitPrice',n(e))}/></td><td class="Fa-Num">{num(x.quantity*x.unitPrice)}</td><td><button class="text-danger" type="button" onclick={()=>update({extras:project.extras.filter(item=>item.id!==x.id)})}>حذف</button></td></tr>{/each}</tbody></table></div>{#if project.extras.length===0}<p class="muted">هنوز قلم جانبی ثبت نشده است. برای دریافت BOQ کامل، اقلام موردنیاز را اضافه کنید.</p>{/if}</div>

